"""Shared types for firmware generators."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Protocol

from puffin.core.issues import Issue, Severity
from puffin.core.models import Firmware, ProjectModel
from puffin.library import PartDefinition, PartLibrary

MARKER = "/* AUTO-GENERATED by Puffin from puffin.yaml -- do not edit */"
"""First line of every generated file. Plain ASCII (see docs/DECISIONS.md)."""

MARKER_PREFIX = b"/* AUTO-GENERATED by Puffin"
"""Prefix that identifies a file Puffin may overwrite."""

GENERATION_CODES: dict[str, Severity] = {
    "name-collision": Severity.ERROR,
    "no-firmware": Severity.ERROR,
    "non-ascii": Severity.WARNING,
    "output-path-collision": Severity.ERROR,
    "output-path-escape": Severity.ERROR,
    "unknown-board": Severity.ERROR,
    "unsupported-framework": Severity.ERROR,
    "unsupported-pin": Severity.ERROR,
}


def gen_issue(code: str, where: str, message: str, hint: str = "") -> Issue:
    return Issue(GENERATION_CODES[code], code, where, message, hint)


@dataclass(frozen=True)
class BoardJob:
    """Everything a generator may read for one board. Generators must not do I/O."""

    model: ProjectModel
    library: PartLibrary
    board: str
    firmware: Firmware
    mcu: str
    part: PartDefinition


@dataclass(frozen=True)
class GeneratedFile:
    board: str
    path: str  # POSIX, relative to the project directory
    content: bytes


@dataclass(frozen=True)
class GenerationResult:
    """Files are returned only when there are no errors."""

    files: list[GeneratedFile]
    issues: list[Issue]

    @property
    def ok(self) -> bool:
        return not any(issue.severity is Severity.ERROR for issue in self.issues)


class Generator(Protocol):
    """Renders one board's firmware file. Pure: no I/O, clocks, or randomness.

    `preflight` reports everything `render` would reject, and must tolerate a model that
    still has validation errors. `render` may assume validation and preflight found no
    errors.
    """

    framework: str

    def preflight(self, job: BoardJob) -> list[Issue]: ...

    def render(self, job: BoardJob) -> bytes: ...
